"""Company matching: normalize both sides, then look for overlap."""

from __future__ import annotations

import re
import string

_LEGAL_RE = re.compile(
    r"\b(ltd|limited|plc|group|holdings|international|uk|engineering|services|"
    r"solutions|systems|technologies|technology|co|inc|gmbh|llc|company|industries|"
    r"manufacturing|the|global|europe|consulting|consultancy|partners|recruitment|"
    r"staffing|personnel|associates|agency|firm|group)\b",
    re.IGNORECASE,
)
_PUNCT_RE = re.compile(r"[^\w\s]")
_SPACE_RE = re.compile(r"\s+")


def normalize_company(name: str) -> frozenset[str]:
    """Lower-case, strip legal suffixes and punctuation, return word tokens."""
    if not name:
        return frozenset()
    s = name.lower()
    s = _LEGAL_RE.sub(" ", s)
    s = _PUNCT_RE.sub(" ", s)
    s = _SPACE_RE.sub(" ", s).strip()
    return frozenset(w for w in s.split() if len(w) > 1)


def build_profile_lookup(companies: list[dict]) -> dict[frozenset, str]:
    """Map normalized token-set → original company name."""
    lookup: dict[frozenset, str] = {}
    for c in companies:
        name = c.get("name", "") if isinstance(c, dict) else str(c)
        tokens = normalize_company(name)
        if tokens:
            lookup[tokens] = name
    return lookup


def match_company(resolved: str, lookup: dict[frozenset, str]) -> str | None:
    """Return the matched profile company name, or None.

    Rules (in order):
    1. Exact token-set equality.
    2. Resolved tokens are a subset of profile tokens (job says "Siemens", profile has "Siemens Energy").
    3. Profile tokens are a subset of resolved tokens (profile says "Deloitte", job says "Deloitte UK Limited").
    """
    r_tokens = normalize_company(resolved)
    if not r_tokens:
        return None
    for p_tokens, name in lookup.items():
        if r_tokens == p_tokens:
            return name
    for p_tokens, name in lookup.items():
        if r_tokens <= p_tokens or p_tokens <= r_tokens:
            return name
    return None

