from __future__ import annotations


def towns_covered(loc: dict) -> frozenset[str]:
    """All city names covered by one profile location entry (lower-cased)."""
    covered = {loc["name"].lower()}
    for inc in loc.get("includes") or []:
        if inc:
            covered.add(inc.lower())
    return frozenset(covered)


def matched_locations(
    resolved_cities: list[str],
    is_remote: bool,
    country: str,
    profile_locations: list[dict],
) -> list[str]:
    """Return every profile location that matches this job.

    Args:
        resolved_cities: City names extracted from the job (lower-cased).
        is_remote: True if the job declared remote/home-based.
        country: Country of the job (lower-cased, e.g. "united kingdom").
        profile_locations: list of location dicts from the profile.
    """
    job_cities = frozenset(c.lower() for c in resolved_cities if c)
    matched: list[str] = []
    for loc in profile_locations:
        loc_country = (loc.get("country") or "").lower()
        loc_type = loc.get("type", "city")

        if loc_country and country and loc_country != country:
            continue

        if loc_type == "remote":
            if is_remote:
                matched.append(loc["name"])
        elif job_cities & towns_covered(loc):
            matched.append(loc["name"])

    return matched

