"""Unit tests for company_matcher utilities."""

from v2.workers.job_matcher.agent.company_matcher import (
    build_profile_lookup,
    match_company,
    normalize_company,
)


def test_normalize_strips_legal_suffixes():
    tokens = normalize_company("Acme Corp Ltd")
    assert "ltd" not in tokens
    assert "acme" in tokens
    assert "corp" in tokens


def test_normalize_empty():
    assert normalize_company("") == frozenset()
